$projRoot = "C:\Users\roberto\source\repos\rednix73\CDB-PESCA-REINOSA\CLub_Deportivo_v2\CLub_Deportivo" $libFolder = Join-Path $projRoot "lib" New-Item -ItemType Directory -Path $libFolder -Force | Out-Null
$packages = @( @{ Id = "NPOI"; Version = "2.6.1" }, @{ Id = "NPOI.OOXML"; Version = "2.6.1" } )
foreach ($p in $packages) { $id = $p.Id $ver = $p.Version $url = "https://www.nuget.org/api/v2/package/$id/$ver" $out = Join-Path $env:TEMP ("$id.$ver.nupkg") $extract = Join-Path $env:TEMP ("$id.$ver") Write-Host "Descargando $id $ver..." try { Invoke-WebRequest -Uri $url -OutFile $out -ErrorAction Stop } catch { Write-Warning "Invoke-WebRequest falló. Intentando Start-BitsTransfer..." try { Start-BitsTransfer -Source $url -Destination $out -ErrorAction Stop } catch { Write-Error "No se pudo descargar $id.$ver desde $url. Comprueba conectividad o descarga manual." continue } }
Remove-Item -Recurse -Force -ErrorAction SilentlyContinue $extract try { Expand-Archive -Path $out -DestinationPath $extract -Force } catch { Write-Error "No se pudo extraer $out" continue }
$cands = @("lib/net48","lib/net45","lib/netstandard2.0","lib/netcoreapp2.0","lib/net40") $found = $null foreach ($c in $cands) { $path = Join-Path $extract $c if (Test-Path $path) { $found = $path; break } } if (-not $found) { Write-Warning "No se encontraron DLLs net* en $id.$ver; busca manualmente en $extract" continue }
$dlls = Get-ChildItem -Path $found -Filter *.dll -ErrorAction SilentlyContinue if (!$dlls) { Write-Warning "No hay DLLs en $found"; continue } foreach ($d in $dlls) { Copy-Item -Path $d.FullName -Destination $libFolder -Force Write-Host "Copiado: $($d.Name) -> $libFolder" }
Remove-Item -Force $out -ErrorAction SilentlyContinue Remove-Item -Recurse -Force $extract -ErrorAction SilentlyContinue }
Write-Host "Operación completada. Añade referencias a las DLL en $libFolder desde Visual Studio (References -> Add Reference -> Browse). Luego Clean / Rebuild."